// src/pages/Login.jsx
import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import axios from "axios";
import { useTheme } from "../context/ThemeContext";
import { useAuth } from "../context/AuthContext";

const Login = () => {
  const { colors } = useTheme();
  const { login } = useAuth();
  const navigate = useNavigate();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    if (!email || !password) {
      setError("Please enter email and password");
      return;
    }

    try {
      const res = await axios.post("/api/v1/token/", {
        email,
        password,
      });

      // ⬇️ ВАЖНО: передаём ВСЁ в AuthContext
      login(res.data);

      navigate("/dashboard");
    } catch (err) {
      setError("Invalid email or password");
    }
  };

  return (
    <div
      style={{
        minHeight: "calc(100vh - 80px)",
        backgroundColor: colors.pageBg,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        padding: "40px 16px",
      }}
    >
      <div
        style={{
          width: "100%",
          maxWidth: "420px",
          backgroundColor: colors.cardBg,
          borderRadius: "18px",
          padding: "32px",
          boxShadow: "0 18px 45px rgba(15,23,42,0.45)",
          color: colors.text,
        }}
      >
        <h2 style={{ textAlign: "center", marginBottom: 8 }}>Log in</h2>

        <p style={{ textAlign: "center", opacity: 0.85, marginBottom: 24 }}>
          Access your dashboard and thesis reports
        </p>

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: 16 }}>
            <label>Email</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              style={{
                width: "100%",
                padding: "10px 14px",
                borderRadius: 999,
              }}
            />
          </div>

          <div style={{ marginBottom: 16 }}>
            <label>Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              style={{
                width: "100%",
                padding: "10px 14px",
                borderRadius: 999,
              }}
            />
          </div>

          {error && (
            <p style={{ color: "#f87171", textAlign: "center" }}>{error}</p>
          )}

          <button
            type="submit"
            style={{
              width: "100%",
              padding: "12px",
              borderRadius: 999,
              background: "linear-gradient(135deg,#fbbf24,#f97316)",
              border: "none",
              fontWeight: 600,
              cursor: "pointer",
            }}
          >
            Log in
          </button>
        </form>

        <p style={{ textAlign: "center", marginTop: 12 }}>
          Don&apos;t have an account?{" "}
          <Link to="/signup" style={{ color: "#fbbf24" }}>
            Sign up
          </Link>
        </p>
      </div>
    </div>
  );
};

export default Login;
